INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 22, 'theory', 'Quiz: iterators');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 22, 0, 'What will iter([1, 2, 3]) return?', '["The list [1, 2, 3]", "An iterator over that list", "The number 1", "An error"]', 1, 'iter returns an iterator: an object that remembers its position and produces values through next.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 22, 1, 'What does a for loop do when the iterator is exhausted?', '["Fails with an error", "Catches StopIteration and quietly leaves the loop", "Starts over", "Returns None"]', 1, 'StopIteration is the signal that the elements ran out; for catches it by itself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 22, 2, 'it = iter([1, 2, 3]); list(it); list(it). What will the second call return?', '["[1, 2, 3]", "[]", "An error", "None"]', 1, 'An iterator is single-use: after the first pass it is exhausted and gives an empty result the second time.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 22, 3, 'What must a class define to become an iterator?', '["__len__ and __getitem__", "__iter__ and __next__", "__enter__ and __exit__", "__init__ and __str__"]', 1, 'The iterator protocol: __iter__ returns the object, and __next__ produces a value or raises StopIteration.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 22, 4, 'Which of these objects are iterators, and not just iterables?', '["list and tuple", "range and str", "an open file and the result of zip", "dict and set"]', 2, 'A file and zip go forward just once; a list, tuple, string, and range can be looped over many times.');
